import { gsap } from 'gsap';
import { Group, Mesh, PlaneGeometry, CylinderGeometry, TorusKnotGeometry, RadialGradient, CanvasTexture, Vector3, Color } from 'three/webgpu';
import { MeshStandardNodeMaterial, MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, vec3, vec4, mix, smoothstep, time, uniform, texture, normalMap, roughnessMap, metalnessMap, clearcoatMap, anisotropyMap } from 'three/tsl';

export default function createNode(config, ctx) {
  const group = new Group();
  const timelines = [];
  const cleanups = [];

  // ============================================================================
  // 1. BACKDROP PLANE (7 x 6 units at z=-3)
  // ============================================================================
  const backdropGeo = new PlaneGeometry(7, 6);
  const backdropMat = new MeshBasicNodeMaterial();

  // Gradient texture from spec: #0b0b10 -> #101017 -> #16161d (vertical, y-major)
  const gradCanvas = document.createElement('canvas');
  gradCanvas.width = 1;
  gradCanvas.height = 512;
  const ctx2d = gradCanvas.getContext('2d');
  const grad = ctx2d.createLinearGradient(0, 0, 0, gradCanvas.height);
  grad.addColorStop(0, '#0b0b10');
  grad.addColorStop(0.7, '#101017');
  grad.addColorStop(1, '#16161d');
  ctx2d.fillStyle = grad;
  ctx2d.fillRect(0, 0, gradCanvas.width, gradCanvas.height);

  const gradTexture = new CanvasTexture(gradCanvas);
  backdropMat.colorNode = texture(gradTexture, uv().mul(vec3(1, 1, 1)).add(vec3(0, 0.5, 0)));

  const backdropMesh = new Mesh(backdropGeo, backdropMat);
  backdropMesh.position.z = -3;
  backdropMesh.renderOrder = 0;
  group.add(backdropMesh);

  // ============================================================================
  // 2. TORUS KNOT (material study hero)
  // ============================================================================
  const knottGeo = new TorusKnotGeometry(0.7, 0.22, 220, 36);
  knottGeo.center();

  // Load brushed metal texture for roughness map
  let roughTexture = null;
  ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
    roughTexture = tex;
    roughTexture.anisotropy = 16;
  });

  // Build TSL node material with anisotropy + clearcoat
  const knotMat = new MeshStandardNodeMaterial();
  knotMat.colorNode = uniform(new Color(0x14141a));

  // Base roughness with map multiplied in center at 0.9
  let roughnessNode = uniform(0.55);
  if (roughTexture) {
    roughnessNode = mix(
      uniform(0.55),
      texture(roughTexture).r.mul(0.9),
      uniform(0.8)
    );
  }
  knotMat.roughnessNode = roughnessNode;
  knotMat.metalness = 0.55;
  knotMat.clearcoat = 0.22;
  knotMat.clearcoatRoughness = 0.35;
  knotMat.anisotropy = 0.9;
  knotMat.anisotropyRotation = Math.PI / 2; // 90 deg rotation to tube direction

  // Scratch noise normal map for imperfection (strength 0.15)
  const scratchCanvas = document.createElement('canvas');
  scratchCanvas.width = 256;
  scratchCanvas.height = 256;
  const scratchCtx = scratchCanvas.getContext('2d');
  scratchCtx.fillStyle = '#8080ff'; // neutral normal (0.5, 0.5, 1)
  scratchCtx.fillRect(0, 0, scratchCanvas.width, scratchCanvas.height);
  // Add fine scratch noise
  for (let i = 0; i < 2000; i++) {
    const x = Math.random() * scratchCanvas.width;
    const y = Math.random() * scratchCanvas.height;
    const len = Math.random() * 8 + 2;
    scratchCtx.strokeStyle = `rgba(128, 128, ${128 + Math.random() * 20}, ${Math.random() * 0.3})`;
    scratchCtx.lineWidth = Math.random() * 0.3 + 0.1;
    scratchCtx.beginPath();
    scratchCtx.moveTo(x, y);
    scratchCtx.lineTo(x + Math.cos(Math.random() * Math.PI * 2) * len, y + Math.sin(Math.random() * Math.PI * 2) * len);
    scratchCtx.stroke();
  }

  const scratchTexture = new CanvasTexture(scratchCanvas);
  knotMat.normalMap = scratchTexture;
  knotMat.normalScale = new Vector3(0.15, 0.15, 0.15);

  const knotMesh = new Mesh(knottGeo, knotMat);
  knotMesh.position.set(0, 0.4, 0);
  knotMesh.castShadow = true;
  knotMesh.receiveShadow = true;
  group.add(knotMesh);

  // ============================================================================
  // 3. PEDESTAL (cylindrical base)
  // ============================================================================
  const pedGeo = new CylinderGeometry(1.1, 1.1, 0.5, 64);
  const pedMat = new MeshStandardNodeMaterial();
  pedMat.color = new Color(0x14141a);
  pedMat.roughness = 0.7;
  pedMat.metalness = 0.35;

  const pedMesh = new Mesh(pedGeo, pedMat);
  pedMesh.position.y = -0.35;
  pedMesh.castShadow = true;
  pedMesh.receiveShadow = true;
  group.add(pedMesh);

  // Chamfered top edge (simple cylinder segment)
  const chamferGeo = new CylinderGeometry(1.1, 1.08, 0.03, 64);
  const chamferMat = new MeshStandardNodeMaterial();
  chamferMat.color = new Color(0x14141a);
  chamferMat.roughness = 0.5;
  chamferMat.metalness = 0.55;
  chamferMat.emissive = new Color(0x1a1a22);

  const chamferMesh = new Mesh(chamferGeo, chamferMat);
  chamferMesh.position.y = -0.16;
  chamferMesh.castShadow = true;
  chamferMesh.receiveShadow = true;
  group.add(chamferMesh);

  // ============================================================================
  // 4. CONTACT SHADOW (radial gradient plane at y=-0.36)
  // ============================================================================
  const shadowGeo = new PlaneGeometry(3, 3);
  const shadowMat = new MeshBasicNodeMaterial();
  shadowMat.transparent = true;

  // Create radial gradient shadow texture
  const shadowCanvas = document.createElement('canvas');
  shadowCanvas.width = 256;
  shadowCanvas.height = 256;
  const shadowCtx = shadowCanvas.getContext('2d');
  const radGrad = shadowCtx.createRadialGradient(128, 128, 0, 128, 128, 128);
  radGrad.addColorStop(0, 'rgba(0, 0, 0, 0.6)');
  radGrad.addColorStop(0.4, 'rgba(0, 0, 0, 0.2)');
  radGrad.addColorStop(1, 'rgba(0, 0, 0, 0)');
  shadowCtx.fillStyle = radGrad;
  shadowCtx.fillRect(0, 0, shadowCanvas.width, shadowCanvas.height);

  const shadowTexture = new CanvasTexture(shadowCanvas);
  shadowMat.map = shadowTexture;

  const shadowMesh = new Mesh(shadowGeo, shadowMat);
  shadowMesh.position.set(0, -0.36, 0.01);
  shadowMesh.scale.set(1.5, 1.5, 1);
  shadowMesh.receiveShadow = false;
  group.add(shadowMesh);

  // ============================================================================
  // 5. LIGHTING
  // ============================================================================
  // Key light (1.2 intensity at 30-45 deg)
  const keyLight = new ctx.THREE.DirectionalLight(0xffffff, 1.2);
  keyLight.position.set(1.5, 2, 1.5);
  keyLight.castShadow = true;
  keyLight.shadow.mapSize.width = 2048;
  keyLight.shadow.mapSize.height = 2048;
  keyLight.shadow.camera.near = 0.1;
  keyLight.shadow.camera.far = 10;
  keyLight.shadow.camera.left = -3;
  keyLight.shadow.camera.right = 3;
  keyLight.shadow.camera.top = 3;
  keyLight.shadow.camera.bottom = -3;
  group.add(keyLight);

  // Rim light (accent-tinted, 0.8 intensity opposite)
  const rimLight = new ctx.THREE.DirectionalLight(0xff4466, 0.8);
  rimLight.position.set(-1.8, 1.2, -1.5);
  group.add(rimLight);

  // Ambient fill via second directional light
  const ambientLight = new ctx.THREE.DirectionalLight(0xccccdd, 0.4);
  ambientLight.position.set(0, 1, 0);
  group.add(ambientLight);

  // ============================================================================
  // 6. TEXT CONTENT
  // ============================================================================
  // Headline: "Material study 03" at 68px 600
  const headlineText = ctx.fontAtlas.createText('Material study 03', {
    fontSize: 68,
    color: '#e8ecf2',
    align: 'center',
    letterSpacingPx: -0.005 * 68
  });
  headlineText.position.set(0, -1.2, 0.1);
  group.add(headlineText);

  // Caption: "GRADE 5 TITANIUM / BRUSHED AT 1200 GRIT" at 18px 400
  const captionText = ctx.fontAtlas.createText('GRADE 5 TITANIUM / BRUSHED AT 1200 GRIT', {
    fontSize: 18,
    color: '#e8ecf2',
    align: 'center',
    letterSpacingPx: 0.08 * 18
  });
  captionText.position.set(0, -1.6, 0.1);
  group.add(captionText);

  // ============================================================================
  // 7. ORBIT ANIMATION (load trigger, speed 0.1 rad/s, radius 0.4)
  // ============================================================================
  const orbitResult = ctx.primitives['orbit'](group, {
    speed: 0.1,
    radius: 0.4,
    trigger: 'load'
  });
  if (orbitResult) {
    cleanups.push(orbitResult.cleanup);
  }

  // ============================================================================
  // 8. CLEANUP & HANDLERS
  // ============================================================================
  group.userData.cleanup = () => {
    timelines.forEach(tl => tl.kill());
    cleanups.forEach(fn => fn && fn());

    knotMat.dispose();
    pedMat.dispose();
    chamferMat.dispose();
    backdropMat.dispose();
    shadowMat.dispose();

    knottGeo.dispose();
    pedGeo.dispose();
    chamferGeo.dispose();
    backdropGeo.dispose();
    shadowGeo.dispose();

    gradTexture.dispose();
    scratchTexture.dispose();
    shadowTexture.dispose();
    if (roughTexture) roughTexture.dispose();
  };

  group.userData.handlers = {};

  return group;
}
